typedef void *pvoid;
typedef char *pchar;
typedef unsigned int MemSize;
typedef unsigned int MemFlags;

class Heap
{
    char data[48];
    MemFlags heapid;
    char remainder[56];

public:
    void AddHeapMemory(pvoid ptr, MemSize size);
    void SetGranularity(MemSize foralloc, MemSize foralign);
    void SetHeapID(MemFlags id) { heapid = id; }
    pvoid Allocate(
        MemSize size,
        MemSize align,
        MemFlags flags,
        const char *name,
        int line);
};

extern Heap heaps[];
extern unsigned int heapsize[];
extern pchar heapmem[];
extern pvoid heapdummyalloc[];
extern const char child_heap_description[];
extern const char dummy_allocation_description[];

void mem_destroy_heap(int heapid);
void *mem_malloc(
    unsigned int size,
    const char *description,
    int line,
    int flags = 0);

__asm__(".equ heaps, 0x00570528");
__asm__(".equ heapsize, 0x005707F8");
__asm__(".equ heapmem, 0x00570810");
__asm__(".equ heapdummyalloc, 0x00570828");
__asm__(".equ child_heap_description, 0x004E9500");
__asm__(".equ dummy_allocation_description, 0x004E9510");
__asm__(".equ mem_destroy_heap__Fi, 0x002ACE18");
__asm__(".equ mem_malloc__FUiPCcii, 0x002AC788");
__asm__(".equ SetGranularity__4HeapUiUi, 0x002AB360");
__asm__(".equ AddHeapMemory__4HeapPvUi, 0x002AB390");
__asm__(".equ Allocate__4HeapUiUiUiPCci, 0x002AB530");

void mem_create_heap(int heapid, int size)
{
    mem_destroy_heap(heapid);

    heapmem[heapid] =
        (char *)mem_malloc(size, child_heap_description, heapid);
    if (heapmem[heapid])
    {
        heapsize[heapid] = size;
        heaps[heapid].SetGranularity(16, 16);
        heaps[heapid].SetHeapID(heapid);
        heaps[heapid].AddHeapMemory(heapmem[heapid], heapsize[heapid]);
        heapdummyalloc[heapid] = heaps[heapid].Allocate(
            4, 1, 0, dummy_allocation_description, 0);
    }
}
